<template><main class="screen page"><header><RouterLink to="/dashboard">‹</RouterLink><div><small>FINANCES</small><b>Budget</b></div><button @click="showForm=!showForm">＋</button></header><section v-if="showForm" class="form-card"><input v-model="form.label" placeholder="Dépense"/><input v-model="form.category" placeholder="Catégorie"/><input v-model.number="form.estimated" type="number" placeholder="Prévu €"/><input v-model.number="form.actual" type="number" placeholder="Dépensé €"/><button @click="addItem">Ajouter</button></section><section class="budget-hero"><span>Budget total</span><h1>{{money(target)}}</h1><div class="numbers"><div><small>Dépensé</small><b>{{money(spent)}}</b></div><div><small>Restant</small><b class="gold">{{money(Math.max(target-spent,0))}}</b></div><strong>{{percent}}%</strong></div><div class="progress"><i :style="{width:percent+'%'}"></i></div></section><div class="title"><h3>Répartition par catégorie</h3><button @click="showForm=!showForm">Ajouter une dépense</button></div><p v-if="loading" class="state">Chargement…</p><section v-else class="items"><article v-for="x in items" :key="x._id"><div class="icon">€</div><div><strong>{{x.category}}</strong><small>{{x.label}}</small><div class="bar"><i :style="{width:Math.min(100,(x.actual/(x.estimated||1))*100)+'%'}"></i></div></div><b>{{money(x.actual)}} <small>/ {{money(x.estimated)}}</small></b></article></section><Nav/></main></template><script setup>
import {computed,onMounted,ref} from 'vue';import {crudApi,getCurrentUser,getWeddingId} from '../services/api.js';const service=crudApi('budget'),items=ref([]),loading=ref(true),showForm=ref(false),form=ref({label:'',category:'',estimated:null,actual:null});const wedding=computed(()=>{const w=getCurrentUser()?.weddings?.[0];return typeof w==='object'?w:null});const target=computed(()=>wedding.value?.budgetTarget||20000),spent=computed(()=>items.value.reduce((s,x)=>s+(x.actual||0),0)),percent=computed(()=>Math.min(100,Math.round(spent.value/(target.value||1)*100)));const money=v=>new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(v||0);async function load(){try{items.value=(await service.list(getWeddingId())).data}finally{loading.value=false}}async function addItem(){if(!form.value.label||!form.value.category)return;const r=await service.create({...form.value,wedding:getWeddingId(),estimated:form.value.estimated||0,actual:form.value.actual||0});items.value.unshift(r.data);form.value={label:'',category:'',estimated:null,actual:null};showForm.value=false}onMounted(load);
</script><style scoped>.page{padding-bottom:105px}header>div{display:grid}header small{font-size:10px;letter-spacing:.15em;color:var(--gold)}header b{font:22px Georgia,serif}.form-card{display:grid;grid-template-columns:repeat(4,1fr) auto;gap:8px;padding:14px;background:#fff8fb;border-radius:18px;margin:12px 0}.form-card input{min-width:0;border:1px solid #eadde1;border-radius:11px;padding:10px}.budget-hero{padding:26px;border-radius:26px;background:linear-gradient(130deg,#fff1f6,#fff,#fff7e9);border:1px solid #f0dfe5;margin:18px 0}.budget-hero>span{font-size:12px;color:#8c7e84}.budget-hero h1{font:42px Georgia,serif;color:#c91f60;margin:8px 0 20px}.numbers{display:grid;grid-template-columns:1fr 1fr auto;align-items:end;gap:20px}.numbers div{display:grid;gap:4px}.numbers small{color:#8c7e84}.numbers b{font-size:18px}.numbers .gold{color:#b87925}.numbers>strong{font-size:22px;color:#c91f60}.progress,.bar{height:8px;background:#f2e6ea;border-radius:999px;overflow:hidden;margin-top:14px}.progress i,.bar i{height:100%;display:block;background:linear-gradient(90deg,#e84d83,#c91f60);border-radius:999px}.title{display:flex;justify-content:space-between;align-items:center}.title button{font-size:11px}.items{display:grid;gap:10px;margin-top:12px}.items article{display:grid;grid-template-columns:44px 1fr auto;align-items:center;gap:13px;background:#fff;border:1px solid #f0e1e6;border-radius:18px;padding:15px}.icon{width:44px;height:44px;display:grid;place-items:center;border-radius:14px;background:#fff0f5;color:#c91f60;font-weight:800}.items article>div:nth-child(2){display:grid;gap:4px}.items small{color:#8c7e84;font-weight:400}.bar{height:5px;margin-top:4px}.items article>b{font-size:13px}.state{text-align:center;padding:40px}@media(max-width:700px){.form-card{grid-template-columns:1fr 1fr}.form-card button{grid-column:1/-1}.budget-hero h1{font-size:34px}.numbers{gap:8px}.items article{grid-template-columns:40px 1fr}.items article>b{grid-column:2}}
</style>